insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position, translations) values ('4431eb1f-361d-4afa-bd58-24ada8e7fef0', 'primer-bocado', 'Primer bocado', 'Sin fuego o con microondas · 100 % seco', 'Para empezar. Todo llega seco y listo para la despensa: tú solo pones agua. Nada de fuegos, como mucho un microondas.', 1, 'chef', '/demo/products/wraps-1.jpg', 1, '{"en":{"name":"First bite","tagline":"No heat or microwave only · 100% dry","description":"To get started. Everything arrives dry and ready for the cupboard: you just add water. No hob, a microwave at most."}}'::jsonb) on conflict (id) do update set translations = excluded.translations;
insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position, translations) values ('dbde67e8-21b6-461d-a6a8-b156c78a67e3', 'con-ganas', 'Con ganas', 'Sartén y cazo · 100 % seco', 'El siguiente paso. Sigue siendo todo seco, pero toca encender el fuego: sartén, cazo y recetas que impresionan. Tú pones agua y un chorrito de aceite.', 2, 'hoja', '/demo/products/ramen-1.jpg', 2, '{"en":{"name":"Getting hungry","tagline":"Pan and pot · 100% dry","description":"The next step. Still all dry, but now you turn on the hob: pans, pots and recipes that impress. You add water and a splash of oil."}}'::jsonb) on conflict (id) do update set translations = excluded.translations;
insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position, translations) values ('e84bca92-d739-4733-b6c4-1abc04efe375', 'hambre-de-mas', 'Hambre de más', 'Recetas del mundo · con ingredientes frescos', 'El reto. Ya sabes cocinar: este kit trae también los ingredientes frescos (carne, verdura, lácteos) y llega refrigerado.', 3, 'teja', '/demo/products/curry-1.jpg', 3, '{"en":{"name":"Hungry for more","tagline":"World recipes · with fresh ingredients","description":"The challenge. You can cook now: these kits also bring the fresh ingredients (meat, fish, veg, dairy) and arrive chilled."}}'::jsonb) on conflict (id) do update set translations = excluded.translations;
insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position, translations) values ('f1cef13a-c34d-4a27-bfd1-cb848b558ac9', 'caja-sorpresa', 'Caja sorpresa', 'Un kit nuevo cada mes', 'No sabrás qué receta te toca hasta abrir la caja. Pago por adelantado de 1, 3 o 6 meses.', null, 'almendra', '/demo/products/sorpresa-1.jpg', 4, '{"en":{"name":"Surprise box","tagline":"A new kit every month","description":"You won''t know which recipe you got until you open the box. Pay upfront for 1, 3 or 6 months."}}'::jsonb) on conflict (id) do update set translations = excluded.translations;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('72475df3-538b-4bb6-9092-e4798f8a662c', 'kit-wraps-crujientes', 'Kit Wraps crujientes', 'Wraps de hummus y verduras crujientes. Sin fuego y sin nevera.', 'Tu primera receta sin encender nada. Tortillas de trigo que aguantan en la despensa, hummus que se prepara con agua en un minuto y verduras liofilizadas que crujen como recién cortadas. Enrollas, cortas y listo.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, null, 120, '{"minutes":15,"difficulty":1,"heat":"sin-fuego","storage":"seco","nutrition":{"kcal":480,"protein":15,"carbs":62,"fat":18}}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'vegetariano']::text[], array['gluten', 'sesamo']::text[], array['soja']::text[], array[]::text[], '{"youAdd":["100 ml de agua"],"steps":[{"title":"Prepara el hummus","text":"Echa el sobre de hummus en un bol, añade 100 ml de agua fría poco a poco y mezcla con un tenedor hasta que quede cremoso."},{"title":"Despierta las verduras","text":"Abre la bolsa de verduras liofilizadas y sacúdela con la mezcla de especias dentro. Quedan crujientes y con sabor."},{"title":"Unta las tortillas","text":"Extiende dos cucharadas de hummus en cada tortilla, dejando un dedo libre en el borde."},{"title":"Rellena y enrolla","text":"Reparte las verduras en una tira en el centro. Dobla los lados hacia dentro y enrolla apretando."},{"title":"Corta y a comer","text":"Corta cada wrap en diagonal con un cuchillo de sierra. Si no te los comes ya, envuélvelos en papel de horno."}],"tips":["Si el hummus queda espeso, añade agua a cucharaditas.","Calienta la tortilla 10 segundos en el microondas para que no se rompa al enrollar."]}'::jsonb, array['6 tortillas de trigo', 'Sobre de hummus (garbanzo y tahini)', 'Verduras crujientes liofilizadas', 'Sobre de especias suaves', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Crunchy wraps kit","subtitle":"Hummus wraps with crunchy veg. No hob and no fridge.","description":"Your first recipe without turning anything on. Wheat tortillas that keep in the cupboard, hummus you make with water in a minute and freeze-dried veg that crunch like they were just cut. Roll, slice, done.","includes":["6 wheat tortillas","Hummus sachet (chickpea and tahini)","Crunchy freeze-dried veg","Mild spice sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"Water."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["100 ml water"],"steps":[{"title":"Make the hummus","text":"Tip the hummus sachet into a bowl, slowly add 100 ml cold water and mix with a fork until creamy."},{"title":"Wake up the veg","text":"Open the bag of freeze-dried veg, add the spice mix and give it a shake. They stay crunchy and full of flavour."},{"title":"Spread the tortillas","text":"Spread two spoonfuls of hummus on each tortilla, leaving a finger-wide gap at the edge."},{"title":"Fill and roll","text":"Lay a strip of veg down the middle. Fold in the sides and roll up tightly."},{"title":"Slice and eat","text":"Cut each wrap diagonally with a serrated knife. If you''re not eating them straight away, wrap them in baking paper."}],"tips":["If the hummus is too thick, add water a teaspoon at a time.","Warm the tortilla for 10 seconds in the microwave so it doesn’t crack when you roll it."]},"variants":{"HDM-WRP-2":"Serves 2","HDM-WRP-4":"Serves 4"},"imageAlts":["Two veggie wraps cut in half","Vegetable wrap rolled up on a plate"]}}'::jsonb, now() - interval '120 days', now() - interval '120 days') on conflict (id) do update set translations = excluded.translations;
