insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('beae607c-9233-4059-8699-6aa67c8de783', 'kit-parfait-frutos-rojos', 'Kit Parfait de frutos rojos', 'Crema de yogur que se monta con agua, granola y frutos rojos.', 'Capas de crema de yogur (viene en polvo y se monta con agua fría), granola con miel y frutos rojos liofilizados que recuperan todo su sabor. Montas cuatro tarros en diez minutos.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, null, 80, '{"minutes":10,"difficulty":1,"heat":"sin-fuego","storage":"seco","nutrition":{"kcal":390,"protein":14,"carbs":55,"fat":12}}'::jsonb, '[{"label":"Tú pones","value":"Agua fría."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegetariano']::text[], array['gluten', 'leche', 'frutos-de-cascara']::text[], array[]::text[], array[]::text[], '{"youAdd":["200 ml de agua muy fría"],"steps":[{"title":"Monta la crema","text":"Mezcla el sobre de crema de yogur con 200 ml de agua muy fría y bate con unas varillas 2 minutos, hasta que espese."},{"title":"Primera capa","text":"Pon dos cucharadas de granola en el fondo de cada vaso o tarro."},{"title":"Crema y fruta","text":"Añade una capa de crema y unos frutos rojos. Repite hasta llenar."},{"title":"Remata","text":"Termina con granola, frutos rojos y una pizca de chía por encima."}],"tips":["Si lo dejas para mañana, guarda la granola aparte para que siga crujiente."]}'::jsonb, array['Sobre de crema de yogur', 'Granola con miel', 'Frutos rojos liofilizados', 'Sobre de semillas de chía', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Berry parfait kit","subtitle":"Yoghurt cream you whip with water, granola and berries.","description":"Layers of yoghurt cream (it comes as a powder and you whip it with cold water), honey granola and freeze-dried berries that get all their flavour back. Four jars in ten minutes.","includes":["Yoghurt cream sachet","Honey granola","Freeze-dried berries","Chia seed sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"Cold water."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["200 ml very cold water"],"steps":[{"title":"Whip the cream","text":"Mix the yoghurt cream sachet with 200 ml very cold water and whisk for 2 minutes until it thickens."},{"title":"First layer","text":"Put two spoonfuls of granola at the bottom of each glass or jar."},{"title":"Cream and fruit","text":"Add a layer of cream and some berries. Repeat until full."},{"title":"Finish","text":"Top with granola, berries and a pinch of chia."}],"tips":["Making it for tomorrow? Keep the granola separate so it stays crunchy."]},"variants":{"HDM-PRF-2":"Serves 2","HDM-PRF-4":"Serves 4"},"imageAlts":["Jars of yoghurt with strawberries","Glass of yoghurt layered with granola and berries"]}}'::jsonb, now() - interval '60 days', now() - interval '60 days') on conflict (id) do update set translations = excluded.translations;
