insert into public.product_variants (id, product_id, sku, name, price_cents, compare_at_price_cents, stock, position) values ('d220e923-5b0a-4f94-90f4-7bd14e9e999a', 'beae607c-9233-4059-8699-6aa67c8de783', 'HDM-PRF-4', '4 personas', 2190, 2490, 30, 1) on conflict (id) do nothing;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('11711508-bff7-4893-8d40-de6e0e3c4111', 'kit-tostadas-aguacate', 'Kit Tostadas de guacamole', 'Guacamole liofilizado, pan crujiente y semillas con chile suave.', 'Guacamole hecho con aguacate liofilizado: se prepara con agua y sabe a recién hecho. Lo untas en pan de masa madre tostado y rematas con nuestra mezcla de semillas y chile suave.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, null, 12, '{"minutes":10,"difficulty":1,"heat":"sin-fuego","storage":"seco","nutrition":{"kcal":420,"protein":11,"carbs":46,"fat":21}}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'vegetariano']::text[], array['gluten', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["80 ml de agua","Opcional, como en la foto: un huevo cocido y unas hojas de espinaca"],"steps":[{"title":"Haz el guacamole","text":"Echa el guacamole en polvo en un bol y añade 80 ml de agua. Mezcla y deja reposar 2 minutos para que se hidrate."},{"title":"Prepara el pan","text":"Saca las rebanadas de pan tostado. Si te gusta templado, 20 segundos en el microondas."},{"title":"Unta","text":"Reparte el guacamole con una cuchara, sin miedo."},{"title":"Remata","text":"Espolvorea las semillas con chile y unas escamas de sal. ¡A comer!"}],"tips":["Para un toque ácido, añade unas gotas de limón si tienes en casa."]}'::jsonb, array['Pan de masa madre tostado', 'Guacamole liofilizado', 'Sobre de semillas y chile suave', 'Sobre de escamas de sal', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Guacamole toast kit","subtitle":"Freeze-dried guacamole, crunchy bread and seeds with mild chilli.","description":"Guacamole made with freeze-dried avocado: you mix it with water and it tastes freshly made. Spread it on toasted sourdough and finish with our seed and mild chilli mix.","includes":["Toasted sourdough bread","Freeze-dried guacamole","Seed and mild chilli sachet","Sea salt flakes sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"Water."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["80 ml water","Optional, like in the photo: a boiled egg and a few spinach leaves"],"steps":[{"title":"Make the guacamole","text":"Tip the guacamole powder into a bowl and add 80 ml water. Mix and leave for 2 minutes to rehydrate."},{"title":"Get the bread ready","text":"Take out the toasted bread. If you like it warm, 20 seconds in the microwave."},{"title":"Spread","text":"Spread the guacamole with a spoon. Be generous."},{"title":"Finish","text":"Sprinkle with the chilli seeds and a few salt flakes. Enjoy!"}],"tips":["For a tangy touch, add a few drops of lemon if you have some at home."]},"variants":{"HDM-TST-2":"Serves 2","HDM-TST-4":"Serves 4"},"imageAlts":["Avocado and egg toast (serving suggestion)","Avocado toast with a poached egg (serving suggestion)"]}}'::jsonb, now() - interval '52 days', now() - interval '52 days') on conflict (id) do update set translations = excluded.translations;
