insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('4e774dec-352d-464f-93d9-80c6d44431e9', 'kit-onigiris-atun', 'Kit Onigiris de atún', 'Bolas de arroz japonés con atún, mayonesa y furikake. Al microondas.', 'El snack japonés más famoso, sin encender el fuego. Arroz japonés ya cocido que se calienta en el microondas, atún en lata, mayonesa y furikake (sésamo y alga) para rebozarlos. Les das forma de triángulo con las manos y los envuelves en alga nori.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, null, 22, '{"minutes":15,"difficulty":1,"heat":"microondas","storage":"seco","nutrition":{"kcal":450,"protein":22,"carbs":68,"fat":9}}'::jsonb, '[{"label":"Tú pones","value":"Nada: solo un microondas."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['sin-gluten']::text[], array['pescado', 'huevos', 'sesamo', 'soja']::text[], array[]::text[], array[]::text[], '{"youAdd":["Nada: solo un microondas y un poco de agua para mojarte las manos"],"steps":[{"title":"Calienta el arroz","text":"Abre un poco la tapa de los vasitos y caliéntalos 1 minuto en el microondas. Deja que se templen para no quemarte."},{"title":"Prepara el relleno","text":"Escurre el atún y mézclalo en un bol con la mayonesa."},{"title":"Forma los onigiris","text":"Mójate las manos, coge un puñado de arroz, haz un hueco en el centro, pon una cucharada de relleno y ciérralo apretando hasta formar un triángulo."},{"title":"Reboza","text":"Pasa los lados por el furikake para que se peguen el sésamo y el alga."},{"title":"Envuelve","text":"Pon una tira de alga nori en la base justo antes de comer, para que cruja."}],"tips":["Con las manos mojadas el arroz no se pega.","Para llevar al instituto, envuelve cada onigiri en film y pon el alga al comer."]}'::jsonb, array['Vasitos de arroz japonés ya cocido', 'Lata de atún al natural', 'Sobre de mayonesa', 'Sobre de furikake (sésamo y alga)', 'Láminas de alga nori', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Tuna onigiri kit","subtitle":"Japanese rice balls with tuna, mayo and furikake. Microwave only.","description":"Japan''s favourite snack, without turning on the hob. Ready-cooked Japanese rice you warm in the microwave, tinned tuna, mayo and furikake (sesame and seaweed) to coat them. Shape them into triangles with your hands and wrap them in nori.","includes":["Cups of ready-cooked Japanese rice","Tin of tuna in water","Mayonnaise sachet","Furikake sachet (sesame and seaweed)","Nori seaweed sheets","Recipe card with QR"],"specs":[{"label":"You add","value":"Nothing: just a microwave."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["Nothing: just a microwave and a little water to wet your hands"],"steps":[{"title":"Warm the rice","text":"Peel back the lid of the rice cups a little and microwave for 1 minute. Let it cool slightly so you don’t burn yourself."},{"title":"Make the filling","text":"Drain the tuna and mix it in a bowl with the mayo."},{"title":"Shape the onigiri","text":"Wet your hands, take a handful of rice, make a dip in the middle, add a spoonful of filling and close it, pressing into a triangle."},{"title":"Coat them","text":"Roll the sides in the furikake so the sesame and seaweed stick."},{"title":"Wrap","text":"Put a strip of nori around the base just before eating so it stays crunchy."}],"tips":["With wet hands the rice won’t stick.","For a school lunch, wrap each onigiri in cling film and add the nori when you eat."]},"variants":{"HDM-ONI-2":"Serves 2","HDM-ONI-4":"Serves 4"},"imageAlts":["Onigiri coated in furikake on a sheet of seaweed (serving suggestion)","Hands holding an onigiri wrapped in seaweed"]}}'::jsonb, now() - interval '38 days', now() - interval '38 days') on conflict (id) do update set translations = excluded.translations;
