insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('68c151dc-d6e5-4a2d-9774-ff0ebc6d8bef', 'kit-mug-cake-chocolate', 'Kit Mug cake de chocolate', 'Bizcocho de chocolate en taza, con corazón fundido. 90 segundos de microondas.', 'El postre más rápido del mundo. Una mezcla de bizcocho de chocolate que ya lleva la leche y el huevo en polvo, pepitas de chocolate para el corazón fundido y un sobre de cacao para decorar. Solo añades agua, remueves en la taza y al microondas.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, 'Nuevo', 34, '{"minutes":5,"difficulty":1,"heat":"microondas","storage":"seco","nutrition":{"kcal":380,"protein":7,"carbs":52,"fat":16}}'::jsonb, '[{"label":"Tú pones","value":"Agua y una taza grande."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegetariano']::text[], array['gluten', 'leche', 'huevos']::text[], array['frutos-de-cascara', 'soja']::text[], array[]::text[], '{"youAdd":["4 cucharadas de agua por taza","Una taza grande apta para microondas"],"steps":[{"title":"Mezcla en la taza","text":"Vacía un sobre de mezcla en una taza grande, añade el agua y remueve con un tenedor hasta que no queden grumos."},{"title":"Esconde el chocolate","text":"Hunde la mitad de las pepitas de chocolate en el centro: será el corazón fundido."},{"title":"Al microondas","text":"90 segundos a máxima potencia. Sube mucho: es normal."},{"title":"Decora","text":"Espera un minuto (la taza quema), espolvorea el cacao y pon el resto de pepitas encima."}],"tips":["Si al pincharlo sale muy líquido, dale 15 segundos más.","Con una bola de helado encima es otro nivel."]}'::jsonb, array['Mezcla de bizcocho de chocolate', 'Pepitas de chocolate', 'Sobre de cacao en polvo', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Chocolate mug cake kit","subtitle":"A chocolate sponge in a mug with a melting centre. 90 seconds in the microwave.","description":"The fastest dessert in the world. A chocolate sponge mix that already contains powdered milk and egg, chocolate chips for the gooey centre and a cocoa sachet to decorate. Just add water, stir in the mug and microwave.","badge":"New","includes":["Chocolate sponge mix","Chocolate chips","Cocoa powder sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and a large mug."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["4 tablespoons water per mug","A large microwave-safe mug"],"steps":[{"title":"Mix in the mug","text":"Empty a sachet of mix into a large mug, add the water and stir with a fork until there are no lumps."},{"title":"Hide the chocolate","text":"Push half the chocolate chips into the middle: that’s the melting centre."},{"title":"Microwave","text":"90 seconds on full power. It rises a lot: that’s normal."},{"title":"Decorate","text":"Wait a minute (the mug is hot), dust with cocoa and scatter the rest of the chips on top."}],"tips":["If it’s still very runny when you poke it, give it 15 more seconds.","With a scoop of ice cream on top it’s next level."]},"variants":{"HDM-MUG-2":"Serves 2","HDM-MUG-4":"Serves 4"},"imageAlts":["Mug with a fluffy chocolate sponge and a spoon (serving suggestion)","Chocolate cake with a molten centre"]}}'::jsonb, now() - interval '1 days', now() - interval '1 days') on conflict (id) do update set translations = excluded.translations;
