insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('a966761b-579e-49f6-bac1-bce9e8031fbc', 'kit-nachos-queso', 'Kit Nachos con queso', 'Totopos de maíz, salsa de queso fundido, jalapeños y maíz dulce.', 'Los nachos de cine, en casa y sin fuego. Totopos de maíz crujientes, una salsa de queso cheddar en polvo que se hace con agua en el microondas, jalapeños en rodajas, maíz dulce y un sobre de especias tex-mex para el toque final.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, null, 90, '{"minutes":10,"difficulty":1,"heat":"microondas","storage":"seco","nutrition":{"kcal":560,"protein":13,"carbs":62,"fat":29}}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegetariano', 'picante']::text[], array['leche']::text[], array['gluten']::text[], array[]::text[], '{"youAdd":["150 ml de agua (2 personas)"],"steps":[{"title":"Haz la salsa","text":"En un bol apto para microondas, mezcla el polvo de queso con el agua. Calienta 1 minuto, remueve y otros 30 segundos hasta que quede cremosa."},{"title":"Monta la bandeja","text":"Extiende los totopos en una fuente grande, sin amontonarlos mucho."},{"title":"Cubre","text":"Reparte la salsa de queso por encima, el maíz escurrido y los jalapeños (pocos si no te va el picante)."},{"title":"Toque final","text":"Espolvorea las especias tex-mex y a comer con las manos."}],"tips":["Si la salsa se espesa, añade una cucharada de agua y remueve.","Perfectos para una noche de peli con amigos."]}'::jsonb, array['Totopos de maíz', 'Salsa de queso cheddar en polvo', 'Jalapeños en rodajas', 'Maíz dulce', 'Sobre de especias tex-mex', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Cheesy nachos kit","subtitle":"Corn tortilla chips, melted cheese sauce, jalapeños and sweet corn.","description":"Cinema nachos at home, no hob needed. Crunchy corn tortilla chips, a powdered cheddar sauce you make with water in the microwave, sliced jalapeños, sweet corn and a Tex-Mex spice sachet for the finishing touch.","includes":["Corn tortilla chips","Powdered cheddar sauce","Sliced jalapeños","Sweet corn","Tex-Mex spice sachet","Recipe card with QR"],"specs":[{"label":"You add","value":"Water."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["150 ml water (serves 2)"],"steps":[{"title":"Make the sauce","text":"In a microwave-safe bowl, mix the cheese powder with the water. Heat 1 minute, stir and another 30 seconds until creamy."},{"title":"Lay out the tray","text":"Spread the chips over a large dish without piling them up too much."},{"title":"Top","text":"Pour the cheese sauce over, then the drained corn and the jalapeños (just a few if you don’t like it hot)."},{"title":"Finish","text":"Sprinkle the Tex-Mex spices and eat with your hands."}],"tips":["If the sauce thickens, add a tablespoon of water and stir.","Perfect for a movie night with friends."]},"variants":{"HDM-NAC-2":"Serves 2","HDM-NAC-4":"Serves 4"},"imageAlts":["Tray of nachos with melted cheese and sweet corn (serving suggestion)","Nachos covered in melted cheese with jalapeños"]}}'::jsonb, now() - interval '45 days', now() - interval '45 days') on conflict (id) do update set translations = excluded.translations;
