insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('3e29b4ae-4520-40c1-b7ef-15a86d8546db', 'kit-bolitas-energeticas', 'Kit Bolitas energéticas de cacao', 'Avena, dátiles, crema de cacahuete y cacao. Sin horno y sin fuego.', 'El snack para antes de entrenar o para el recreo. Copos de avena, dátiles troceados, crema de cacahuete y cacao puro: lo mezclas todo, formas bolitas con las manos y las rebozas en cacao. Salen unas 16 bolitas por cada 2 personas.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, null, 26, '{"minutes":15,"difficulty":1,"heat":"sin-fuego","storage":"seco","nutrition":{"kcal":420,"protein":12,"carbs":52,"fat":17}}'::jsonb, '[{"label":"Tú pones","value":"Un poco de agua templada."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano']::text[], array['gluten', 'cacahuetes']::text[], array['frutos-de-cascara', 'sesamo']::text[], array[]::text[], '{"youAdd":["2 cucharadas de agua templada"],"steps":[{"title":"Ablanda los dátiles","text":"Pon los dátiles en un bol con el agua templada 5 minutos y aplástalos con un tenedor hasta hacer una pasta."},{"title":"Mezcla","text":"Añade la avena, la crema de cacahuete y la mitad del cacao. Mezcla con las manos hasta que se pegue todo."},{"title":"Forma las bolitas","text":"Coge porciones del tamaño de una nuez y hazlas rodar entre las palmas."},{"title":"Reboza","text":"Pásalas por el resto del cacao y guárdalas en la nevera 15 minutos para que cojan cuerpo."}],"tips":["Si la masa está muy seca, añade unas gotas de agua; si está muy blanda, un poco más de avena.","En un táper en la nevera aguantan 5 días."]}'::jsonb, array['Copos de avena', 'Dátiles troceados', 'Crema de cacahuete', 'Cacao puro en polvo', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Cocoa energy balls kit","subtitle":"Oats, dates, peanut butter and cocoa. No oven, no hob.","description":"The snack for before training or break time. Rolled oats, chopped dates, peanut butter and pure cocoa: mix it all, roll into balls with your hands and coat them in cocoa. About 16 balls for every 2 servings.","includes":["Rolled oats","Chopped dates","Peanut butter","Pure cocoa powder","Recipe card with QR"],"specs":[{"label":"You add","value":"A little warm water."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["2 tablespoons warm water"],"steps":[{"title":"Soften the dates","text":"Put the dates in a bowl with the warm water for 5 minutes and mash them with a fork into a paste."},{"title":"Mix","text":"Add the oats, the peanut butter and half the cocoa. Mix with your hands until it all sticks together."},{"title":"Roll the balls","text":"Take walnut-sized pieces and roll them between your palms."},{"title":"Coat","text":"Roll them in the rest of the cocoa and chill for 15 minutes to firm up."}],"tips":["If the mix is too dry, add a few drops of water; too soft, a little more oats.","They keep 5 days in a tub in the fridge."]},"variants":{"HDM-BOL-2":"Serves 2","HDM-BOL-4":"Serves 4"},"imageAlts":["Cocoa-dusted energy balls on a plate (serving suggestion)","Oat and nut energy balls"]}}'::jsonb, now() - interval '56 days', now() - interval '56 days') on conflict (id) do update set translations = excluded.translations;
