insert into public.product_variants (id, product_id, sku, name, price_cents, compare_at_price_cents, stock, position) values ('e8cd234e-ab90-4721-b103-d8bc865d393f', '3e29b4ae-4520-40c1-b7ef-15a86d8546db', 'HDM-BOL-4', '4 personas', 1990, null, 22, 1) on conflict (id) do nothing;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('629ead1c-9bd7-4841-b3b5-9b7a000c741f', 'kit-ramen-casero', 'Kit Ramen casero', 'Caldo de miso, fideos ramen y toppings deshidratados. El que te convierte en chef.', 'Nuestro kit estrella y 100 % de despensa. Fideos ramen de verdad, caldo de miso, setas shiitake y cebolleta deshidratadas, alga nori y aceite de chile y sésamo. Un bol que no tiene nada que envidiar al de tu restaurante favorito.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', true, true, 'Más vendido', 340, '{"minutes":25,"difficulty":2,"heat":"cazo","storage":"seco","nutrition":{"kcal":520,"protein":17,"carbs":82,"fat":13}}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array[]::text[], array['gluten', 'soja', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["1 litro de agua (2 personas)"],"steps":[{"title":"Hidrata las setas","text":"Pon las setas shiitake en un vaso con agua caliente del grifo 10 minutos. Guarda esa agua: tiene mucho sabor."},{"title":"Haz el caldo","text":"En un cazo, calienta el agua (incluida la de las setas). Cuando hierva, baja el fuego y disuelve el caldo de miso removiendo. Que no vuelva a hervir fuerte."},{"title":"Cuece los fideos","text":"En otro cazo con agua hirviendo, cuece los fideos 3 minutos. Escúrrelos y repártelos en los boles."},{"title":"Monta el bol","text":"Vierte el caldo caliente sobre los fideos. Añade las setas escurridas y la cebolleta."},{"title":"Toque final","text":"Pon un trozo de alga nori en el borde del bol y unas gotas de aceite de chile y sésamo. ¡Itadakimasu!"}],"tips":["Los fideos se cuecen aparte para que el caldo no quede turbio.","Más picante: más aceite de chile. Menos: solo sésamo."]}'::jsonb, array['Fideos ramen', 'Sobre de caldo de miso', 'Setas shiitake deshidratadas', 'Cebolleta liofilizada', 'Alga nori', 'Aceite de chile y sésamo', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Homemade ramen kit","subtitle":"Miso broth, ramen noodles and dried toppings. The one that turns you into a chef.","description":"Our star kit, and 100% cupboard food. Real ramen noodles, miso broth, dried shiitake mushrooms and spring onion, nori seaweed and chilli-sesame oil. A bowl that’s as good as your favourite restaurant’s.","badge":"Best seller","includes":["Ramen noodles","Miso broth sachet","Dried shiitake mushrooms","Freeze-dried spring onion","Nori seaweed","Chilli and sesame oil","Recipe card with QR"],"specs":[{"label":"You add","value":"Water."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["1 litre water (serves 2)"],"steps":[{"title":"Soak the mushrooms","text":"Put the shiitake in a glass of hot tap water for 10 minutes. Keep that water: it’s full of flavour."},{"title":"Make the broth","text":"Heat the water in a pot (including the mushroom water). When it boils, turn the heat down and stir in the miso broth. Don’t let it boil hard again."},{"title":"Cook the noodles","text":"In another pot of boiling water, cook the noodles for 3 minutes. Drain and share them between the bowls."},{"title":"Build the bowl","text":"Pour the hot broth over the noodles. Add the drained mushrooms and the spring onion."},{"title":"Final touch","text":"Tuck a piece of nori at the edge of the bowl and add a few drops of chilli-sesame oil. Itadakimasu!"}],"tips":["Cook the noodles separately so the broth stays clear.","Spicier: more chilli oil. Milder: sesame only."]},"variants":{"HDM-RAM-2":"Serves 2","HDM-RAM-4":"Serves 4"},"imageAlts":["Bowl of miso ramen with shiitake mushrooms, spring onion and chilli oil (serving suggestion)","Ramen noodles lifted with chopsticks from a creamy broth with mushrooms"]}}'::jsonb, now() - interval '150 days', now() - interval '150 days') on conflict (id) do update set translations = excluded.translations;
