insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('0c200051-60e5-4fc6-a384-c3bbeb69ff10', 'kit-tacos-al-pastor', 'Kit Tacos al pastor', 'Soja texturizada al pastor, tortillas de maíz y salsa de piña.', 'Tacos con soja texturizada marinada en adobo al pastor, hechos a la sartén. Textura de carne picada sin necesidad de nevera. El kit trae las tortillas de maíz y una salsa de piña con un punto picante.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', true, true, 'Más vendido', 175, '{"minutes":25,"difficulty":2,"heat":"sarten","storage":"seco","nutrition":{"kcal":540,"protein":30,"carbs":62,"fat":17}}'::jsonb, '[{"label":"Tú pones","value":"Agua y un chorrito de aceite."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'picante', 'sin-gluten', 'alto-en-proteina']::text[], array['soja']::text[], array['gluten']::text[], array[]::text[], '{"youAdd":["300 ml de agua caliente","2 cucharadas de aceite"],"steps":[{"title":"Hidrata la soja","text":"Cubre la soja texturizada con agua caliente 10 minutos. Escúrrela apretando con una cuchara."},{"title":"Marina","text":"Mezcla la soja con el adobo al pastor y deja que coja sabor mientras calientas la sartén."},{"title":"Dora en la sartén","text":"Sartén a fuego medio-alto con el aceite. Saltea la soja 6-8 minutos hasta que se dore por los bordes."},{"title":"Calienta las tortillas","text":"En la misma sartén, ya sin aceite, 20 segundos por cada lado."},{"title":"Monta los tacos","text":"Tortilla, soja al pastor, salsa de piña y cebolla crujiente. Dobla y muerde."}],"tips":["Apila las tortillas calientes envueltas en un paño para que no se sequen."]}'::jsonb, array['Soja texturizada', 'Sobre de adobo al pastor', '12 tortillas de maíz', 'Salsa de piña y chile', 'Cebolla crujiente', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Tacos al pastor kit","subtitle":"Al pastor textured soy, corn tortillas and pineapple salsa.","description":"Tacos with textured soy marinated in al pastor adobo, cooked in a pan. The texture of minced meat with no fridge needed. The kit brings the corn tortillas and a pineapple salsa with a little kick.","badge":"Best seller","includes":["Textured soy","Al pastor adobo sachet","12 corn tortillas","Pineapple and chilli salsa","Crispy onion","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and a splash of oil."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["300 ml hot water","2 tablespoons oil"],"steps":[{"title":"Soak the soy","text":"Cover the textured soy with hot water for 10 minutes. Drain it, pressing with a spoon."},{"title":"Marinate","text":"Mix the soy with the al pastor adobo and let it soak up the flavour while the pan heats."},{"title":"Brown it","text":"Pan on medium-high heat with the oil. Fry the soy for 6–8 minutes until golden at the edges."},{"title":"Warm the tortillas","text":"In the same pan, now without oil, 20 seconds each side."},{"title":"Build the tacos","text":"Tortilla, al pastor soy, pineapple salsa and crispy onion. Fold and bite."}],"tips":["Stack the warm tortillas wrapped in a tea towel so they don’t dry out."]},"variants":{"HDM-TAC-2":"Serves 2","HDM-TAC-4":"Serves 4"},"imageAlts":["Plate with three veggie tacos","Vegetable tacos with lime"]}}'::jsonb, now() - interval '100 days', now() - interval '100 days') on conflict (id) do update set translations = excluded.translations;
