insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('e0071f2f-aed1-4d02-b0ed-7ecd144daa10', 'kit-pad-thai', 'Kit Pad thai', 'Fideos de arroz salteados con salsa de tamarindo, tofu y cacahuetes.', 'El plato callejero más famoso de Tailandia, 100 % de despensa. Fideos de arroz planos, salsa pad thai de tamarindo, tofu firme envasado que no necesita nevera, cacahuetes tostados, cebolleta liofilizada y escamas de chile para quien se atreva.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', false, true, 'Nuevo', 30, '{"minutes":20,"difficulty":2,"heat":"sarten","storage":"seco","nutrition":{"kcal":590,"protein":19,"carbs":80,"fat":21}}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano']::text[], array['soja', 'cacahuetes', 'gluten']::text[], array['sesamo']::text[], array[]::text[], '{"youAdd":["Agua caliente para remojar los fideos","2 cucharadas de aceite"],"steps":[{"title":"Remoja los fideos","text":"Cubre los fideos con agua caliente del grifo 10 minutos, hasta que estén flexibles. Escúrrelos."},{"title":"Dora el tofu","text":"Corta el tofu en dados y dóralo en la sartén con el aceite a fuego medio-alto, 5 minutos."},{"title":"Saltea","text":"Añade los fideos y la salsa pad thai. Remueve sin parar 2-3 minutos hasta que los fideos se tiñan y queden sueltos."},{"title":"Termina","text":"Sirve con los cacahuetes picados, la cebolleta y las escamas de chile al gusto."}],"tips":["No remojes los fideos en agua hirviendo: se rompen al saltear.","Con un chorrito de lima encima queda todavía mejor."]}'::jsonb, array['Fideos de arroz planos', 'Salsa pad thai de tamarindo', 'Tofu firme envasado', 'Cacahuetes tostados', 'Cebolleta liofilizada', 'Escamas de chile', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Pad thai kit","subtitle":"Stir-fried rice noodles with tamarind sauce, tofu and peanuts.","description":"Thailand’s most famous street dish, 100% from the cupboard. Flat rice noodles, tamarind pad thai sauce, shelf-stable firm tofu that needs no fridge, roasted peanuts, freeze-dried spring onion and chilli flakes for the brave.","badge":"New","includes":["Flat rice noodles","Tamarind pad thai sauce","Shelf-stable firm tofu","Roasted peanuts","Freeze-dried spring onion","Chilli flakes","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and oil."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["Hot water to soak the noodles","2 tablespoons oil"],"steps":[{"title":"Soak the noodles","text":"Cover the noodles with hot tap water for 10 minutes until flexible. Drain."},{"title":"Brown the tofu","text":"Dice the tofu and brown it in the pan with the oil over medium-high heat, 5 minutes."},{"title":"Stir-fry","text":"Add the noodles and the pad thai sauce. Keep stirring 2–3 minutes until the noodles are coated and loose."},{"title":"Finish","text":"Serve with chopped peanuts, spring onion and chilli flakes to taste."}],"tips":["Don’t soak the noodles in boiling water: they break when you stir-fry.","A squeeze of lime on top makes it even better."]},"variants":{"HDM-PAD-2":"Serves 2","HDM-PAD-4":"Serves 4"},"imageAlts":["Plate of pad thai with rice noodles, bean sprouts and chives (serving suggestion)","Pad thai with peanuts, bean sprouts, chives and lemon"]}}'::jsonb, now() - interval '2 days', now() - interval '2 days') on conflict (id) do update set translations = excluded.translations;
