insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('6f1184c2-4d30-4555-b9ae-9d6cfd5ae58f', 'kit-risotto-setas', 'Kit Risotto de setas', 'Arroz arborio cremoso con boletus, caldo de verduras y parmesano.', 'Un clásico italiano que se cocina removiendo con paciencia. Arroz arborio, boletus deshidratados con todo su aroma, caldo de verduras en polvo, cebolla deshidratada y queso parmesano curado rallado. El resultado: un arroz meloso de restaurante.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', false, true, null, 110, '{"minutes":35,"difficulty":2,"heat":"cazo","storage":"seco","nutrition":{"kcal":560,"protein":15,"carbs":82,"fat":17}}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite de oliva."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegetariano', 'sin-gluten']::text[], array['leche', 'apio']::text[], array[]::text[], array[]::text[], '{"youAdd":["900 ml de agua (2 personas)","2 cucharadas de aceite de oliva"],"steps":[{"title":"Hidrata las setas","text":"Pon los boletus en un vaso con agua caliente 10 minutos. Escúrrelos y guarda el agua."},{"title":"Prepara el caldo","text":"Calienta el resto del agua con el caldo en polvo y el agua de las setas. Mantenlo caliente a fuego bajo."},{"title":"Nacara el arroz","text":"En otro cazo, calienta el aceite con la cebolla deshidratada y las setas 2 minutos. Añade el arroz y remueve 1 minuto."},{"title":"Caldo poco a poco","text":"Añade un cazo de caldo y remueve hasta que el arroz lo absorba. Repite durante unos 18 minutos."},{"title":"Manteca","text":"Fuera del fuego, añade el parmesano, remueve con energía y deja reposar 2 minutos tapado."}],"tips":["Remover suelta el almidón: por eso queda cremoso sin nata.","Tiene que quedar meloso, no seco: si hace falta, un poco más de caldo."]}'::jsonb, array['Arroz arborio', 'Boletus deshidratados', 'Caldo de verduras en polvo', 'Cebolla deshidratada', 'Parmesano curado rallado', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Mushroom risotto kit","subtitle":"Creamy arborio rice with porcini, vegetable stock and parmesan.","description":"An Italian classic you cook by stirring patiently. Arborio rice, dried porcini full of aroma, vegetable stock powder, dried onion and grated aged parmesan. The result: a restaurant-style creamy rice.","includes":["Arborio rice","Dried porcini mushrooms","Vegetable stock powder","Dried onion","Grated aged parmesan","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and olive oil."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["900 ml water (serves 2)","2 tablespoons olive oil"],"steps":[{"title":"Soak the mushrooms","text":"Put the porcini in a glass of hot water for 10 minutes. Drain them and keep the water."},{"title":"Make the stock","text":"Heat the rest of the water with the stock powder and the mushroom water. Keep it hot over low heat."},{"title":"Toast the rice","text":"In another pot, heat the oil with the dried onion and the mushrooms for 2 minutes. Add the rice and stir for 1 minute."},{"title":"Stock bit by bit","text":"Add a ladle of stock and stir until the rice absorbs it. Repeat for about 18 minutes."},{"title":"Finish","text":"Off the heat, add the parmesan, stir hard and let it rest, covered, for 2 minutes."}],"tips":["Stirring releases the starch: that’s why it’s creamy without cream.","It should be loose, not dry: add a little more stock if needed."]},"variants":{"HDM-RIS-2":"Serves 2","HDM-RIS-4":"Serves 4"},"imageAlts":["Creamy mushroom risotto with parsley in a dark bowl (serving suggestion)","Mushroom risotto with parmesan and chives"]}}'::jsonb, now() - interval '60 days', now() - interval '60 days') on conflict (id) do update set translations = excluded.translations;
