insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('32e5f017-99b8-4808-a051-5099b4fa681a', 'kit-chili-sin-carne', 'Kit Chili sin carne', 'Alubias rojas, soja texturizada, tomate y especias mexicanas. Picante y reconfortante.', 'Un guiso tex-mex que no echa de menos la carne. Alubias rojas cocidas, soja texturizada, tomate triturado, maíz dulce y una mezcla de especias con comino, pimentón y chile. Todo de despensa y listo en una cazuela.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', false, true, null, 95, '{"minutes":30,"difficulty":2,"heat":"cazo","storage":"seco","nutrition":{"kcal":470,"protein":28,"carbs":62,"fat":9}}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'sin-gluten', 'picante', 'alto-en-proteina']::text[], array['soja']::text[], array['apio']::text[], array[]::text[], '{"youAdd":["250 ml de agua","1 cucharada de aceite"],"steps":[{"title":"Hidrata la soja","text":"Pon la soja texturizada en un bol con agua caliente 10 minutos y escúrrela apretando bien."},{"title":"Sofríe","text":"En una cazuela con el aceite, rehoga la cebolla deshidratada y la soja 3 minutos. Añade las especias y remueve 30 segundos."},{"title":"Guisa","text":"Echa el tomate, las alubias escurridas, el maíz y el agua. Cuando hierva, baja el fuego y deja 15 minutos removiendo de vez en cuando."},{"title":"Sirve","text":"Prueba de sal y sírvelo bien caliente. Con arroz, totopos o pan, como más te guste."}],"tips":["Al día siguiente está todavía más rico.","Menos picante: pon solo la mitad del sobre de especias."]}'::jsonb, array['Alubias rojas cocidas', 'Soja texturizada', 'Tomate triturado en brick', 'Maíz dulce', 'Mezcla de especias chili', 'Cebolla deshidratada', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Chilli sin carne kit","subtitle":"Red kidney beans, textured soy, tomato and Mexican spices. Spicy and comforting.","description":"A Tex-Mex stew that doesn’t miss the meat. Cooked red kidney beans, textured soy, crushed tomato, sweet corn and a spice mix with cumin, paprika and chilli. All from the cupboard and ready in one pot.","includes":["Cooked red kidney beans","Textured soy","Crushed tomato carton","Sweet corn","Chilli spice mix","Dried onion","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and oil."},{"label":"Storage","value":"Cupboard: cool, dry place. Best before: 6 months from shipping."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["250 ml water","1 tablespoon oil"],"steps":[{"title":"Soak the soy","text":"Put the textured soy in a bowl of hot water for 10 minutes and squeeze it dry."},{"title":"Fry","text":"In a pot with the oil, cook the dried onion and the soy for 3 minutes. Add the spices and stir for 30 seconds."},{"title":"Simmer","text":"Add the tomato, the drained beans, the corn and the water. When it boils, lower the heat and cook for 15 minutes, stirring now and then."},{"title":"Serve","text":"Season to taste and serve piping hot. With rice, tortilla chips or bread, however you like."}],"tips":["It’s even tastier the next day.","Less spicy: use only half the spice sachet."]},"variants":{"HDM-CHL-2":"Serves 2","HDM-CHL-4":"Serves 4"},"imageAlts":["Bowl of red bean chilli with avocado and yoghurt (serving suggestion)","Red bean and corn chilli with yoghurt and spring onion (serving suggestion)"]}}'::jsonb, now() - interval '40 days', now() - interval '40 days') on conflict (id) do update set translations = excluded.translations;
