insert into public.product_variants (id, product_id, sku, name, price_cents, compare_at_price_cents, stock, position) values ('2e725645-346d-4ace-9a83-e30345ec1724', '9cd23a54-a303-49f7-8245-387ac19888f5', 'HDM-CUR-4', '4 personas', 4690, 5580, 14, 1) on conflict (id) do nothing;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('0a53aa7d-4cf2-4f64-847a-ecd3b303d8ca', 'kit-butter-chicken', 'Kit Butter chicken con naan', 'Pollo fresco en salsa de tomate, mantequilla y garam masala.', 'El plato indio que gusta a todo el mundo. Llega refrigerado con los muslos de pollo, el yogur, la nata y la mantequilla; además, especias, tomate y la mezcla para hacer naan en la sartén. Es de Hambre de más porque hay que coordinar tres elaboraciones a la vez.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, 'Más vendido', 150, '{"minutes":50,"difficulty":3,"heat":"sarten","storage":"fresco","nutrition":{"kcal":720,"protein":36,"carbs":70,"fat":31}}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['alto-en-proteina']::text[], array['gluten', 'leche']::text[], array[]::text[], array[]::text[], '{"youAdd":["120 ml de agua (para el naan)"],"steps":[{"title":"Marina el pollo","text":"Corta el pollo en trozos y mézclalo con la mitad del yogur y las especias del marinado. Deja 15 minutos en la nevera."},{"title":"Masa de naan","text":"Mezcla la harina de naan con el resto del yogur y 120 ml de agua. Amasa 3 minutos y deja reposar tapada."},{"title":"Dora el pollo","text":"Sartén caliente con la mitad de la mantequilla. Dora el pollo 6 minutos y sácalo."},{"title":"La salsa","text":"En la misma sartén, el resto de la mantequilla, el tomate y el garam masala 3 minutos. Añade la nata y vuelve a meter el pollo 10 minutos a fuego suave."},{"title":"Naan a la sartén","text":"Divide la masa en bolas, estíralas finas y cocínalas en una sartén sin aceite muy caliente, 1 minuto por lado, hasta que hagan burbujas."},{"title":"Sirve","text":"Butter chicken en un bol y naan caliente al lado para mojar."}],"tips":["Con tres cosas a la vez, prepara todo antes de encender el fuego."]}'::jsonb, array['Muslos de pollo frescos', 'Yogur natural, nata y mantequilla', 'Sobres de garam masala y especias del marinado', 'Tomate concentrado', 'Mezcla para naan', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Butter chicken with naan kit","subtitle":"Fresh chicken in a tomato, butter and garam masala sauce.","description":"The Indian dish everybody loves. It arrives chilled with the chicken thighs, yoghurt, cream and butter, plus spices, tomato and the mix to make naan in a pan. It’s Hungry for more because you juggle three things at once.","badge":"Best seller","includes":["Fresh chicken thighs","Plain yoghurt, cream and butter","Garam masala and marinade spice sachets","Tomato purée","Naan mix","Recipe card with QR"],"specs":[{"label":"You add","value":"Water."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["120 ml water (for the naan)"],"steps":[{"title":"Marinate the chicken","text":"Cut the chicken into pieces and mix with half the yoghurt and the marinade spices. Leave in the fridge for 15 minutes."},{"title":"Naan dough","text":"Mix the naan flour with the rest of the yoghurt and 120 ml water. Knead for 3 minutes and leave to rest, covered."},{"title":"Brown the chicken","text":"Hot pan with half the butter. Brown the chicken for 6 minutes and take it out."},{"title":"The sauce","text":"In the same pan, the rest of the butter, the tomato and the garam masala for 3 minutes. Add the cream and return the chicken for 10 minutes on gentle heat."},{"title":"Pan naan","text":"Divide the dough into balls, roll them thin and cook in a very hot dry pan, 1 minute each side, until they bubble."},{"title":"Serve","text":"Butter chicken in a bowl and hot naan on the side for dipping."}],"tips":["With three things going at once, get everything ready before you turn on the hob."]},"variants":{"HDM-BTC-2":"Serves 2","HDM-BTC-4":"Serves 4"},"imageAlts":["Butter chicken with naan bread","Bowls of Indian curry with rice"]}}'::jsonb, now() - interval '70 days', now() - interval '70 days') on conflict (id) do update set translations = excluded.translations;
