insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('c4cf16d7-722c-4932-a9b3-d2fdc678c730', 'kit-gyozas-caseras', 'Kit Gyozas caseras', 'Obleas frescas, relleno de cerdo y col, y salsa ponzu.', 'El reto de Hambre de más: cerrar gyozas con sus pliegues. Llega refrigerado con las obleas, la carne picada y la col; además, especias para el relleno y salsa ponzu para mojar. Te enseñamos el pliegue y la técnica de vapor y sartén.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 18, '{"minutes":60,"difficulty":3,"heat":"sarten","storage":"fresco","nutrition":{"kcal":520,"protein":19,"carbs":60,"fat":20}}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array[]::text[], array['gluten', 'soja', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["Un vasito de agua","1 cucharada de aceite"],"steps":[{"title":"Relleno","text":"Pica la col y la cebolleta muy finas. Mézclalas con la carne y las especias hasta que quede una pasta."},{"title":"Rellena","text":"Pon una cucharadita de relleno en el centro de cada oblea y moja el borde con un dedo húmedo."},{"title":"El pliegue","text":"Dobla por la mitad y, desde un extremo, haz 5 o 6 pliegues en la cara de delante, apretando contra la de detrás."},{"title":"Dora","text":"Sartén con aceite a fuego medio. Coloca las gyozas de pie y dóralas 2 minutos por la base."},{"title":"Vapor","text":"Echa medio vaso de agua y tapa enseguida (¡cuidado con las salpicaduras!). Cocina 6 minutos hasta que se evapore el agua."},{"title":"Sirve","text":"Con la base crujiente hacia arriba y ponzu con sésamo para mojar."}],"tips":["Las primeras quedan feas: a la décima te salen perfectas.","Puedes congelarlas crudas y cocinarlas otro día."]}'::jsonb, array['30 obleas para gyozas', 'Carne picada de cerdo fresca', 'Col y cebolleta frescas', 'Sobre de especias para el relleno', 'Salsa ponzu', 'Aceite de sésamo', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Homemade gyoza kit","subtitle":"Fresh wrappers, pork and cabbage filling, and ponzu sauce.","description":"The Hungry for more challenge: sealing gyozas with their pleats. It arrives chilled with the wrappers, minced pork and cabbage, plus filling spices and ponzu sauce for dipping. We teach you the pleat and the steam-and-fry technique.","includes":["30 gyoza wrappers","Fresh minced pork","Fresh cabbage and spring onion","Filling spice sachet","Ponzu sauce","Sesame oil","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and oil."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["A small glass of water","1 tablespoon oil"],"steps":[{"title":"Filling","text":"Chop the cabbage and spring onion very finely. Mix with the meat and spices into a paste."},{"title":"Fill","text":"Put a teaspoon of filling in the centre of each wrapper and wet the edge with a damp finger."},{"title":"The pleat","text":"Fold in half and, starting at one end, make 5 or 6 pleats on the front side, pressing against the back."},{"title":"Brown","text":"Pan with oil on medium heat. Stand the gyozas up and brown the bottoms for 2 minutes."},{"title":"Steam","text":"Pour in half a glass of water and cover straight away (watch out for splashes!). Cook for 6 minutes until the water evaporates."},{"title":"Serve","text":"Crispy side up, with ponzu and sesame for dipping."}],"tips":["The first ones look ugly: by the tenth they’ll be perfect.","You can freeze them raw and cook them another day."]},"variants":{"HDM-GYO-2":"Serves 2","HDM-GYO-4":"Serves 4"},"imageAlts":["Steamed gyozas in a bamboo steamer","Pan-fried golden gyozas"]}}'::jsonb, now() - interval '62 days', now() - interval '62 days') on conflict (id) do update set translations = excluded.translations;
