insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('6c0cf2f9-8833-4fa4-8699-8cbb8feb3e5e', 'kit-pizza-napolitana', 'Kit Pizza napolitana', 'Masa de larga fermentación, mozzarella fresca y albahaca.', 'Harina tipo 00, levadura y tomate San Marzano, más los frescos: mozzarella fior di latte y albahaca. Estiras a mano, horneas a máxima potencia y consigues un borde inflado y tostado.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, 'Más vendido', 260, '{"minutes":45,"difficulty":3,"heat":"horno","storage":"fresco","nutrition":{"kcal":780,"protein":24,"carbs":104,"fat":26}}'::jsonb, '[{"label":"Tú pones","value":"Agua templada y aceite de oliva."},{"label":"Tiempo de reposo","value":"La masa necesita entre 8 y 24 horas de reposo en nevera."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegetariano']::text[], array['gluten', 'leche']::text[], array[]::text[], array[]::text[], '{"youAdd":["300 ml de agua templada","1 cucharada de aceite de oliva"],"steps":[{"title":"La masa (el día antes)","text":"Mezcla la harina, la levadura, una cucharadita de sal y el agua templada. Amasa 10 minutos hasta que esté lisa, haz bolas y guárdalas tapadas en la nevera de 8 a 24 horas."},{"title":"Atempera","text":"Saca las bolas de la nevera 1 hora antes y pon el horno a la máxima temperatura con la bandeja dentro."},{"title":"Estira a mano","text":"Aplasta la bola desde el centro hacia fuera, dejando el borde gordito. Nada de rodillo: aplastaría el aire."},{"title":"Monta","text":"Tomate aplastado con la mano, mozzarella escurrida y troceada, un chorrito de aceite."},{"title":"Hornea","text":"Sobre la bandeja caliente, 7-9 minutos hasta que el borde esté inflado y con manchas tostadas."},{"title":"Albahaca","text":"Al sacarla, unas hojas de albahaca fresca. Corta y comparte (o no)."}],"tips":["Usa guantes de horno para sacar la bandeja: está ardiendo."]}'::jsonb, array['Harina tipo 00', 'Sobre de levadura seca', 'Tomate San Marzano', 'Mozzarella fior di latte fresca', 'Albahaca fresca', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Neapolitan pizza kit","subtitle":"Slow-proved dough, fresh mozzarella and basil.","description":"Type 00 flour, yeast and San Marzano tomatoes, plus the fresh stuff: fior di latte mozzarella and basil. Stretch by hand, bake at full power and get a puffy, charred crust.","badge":"Best seller","includes":["Type 00 flour","Dried yeast sachet","San Marzano tomatoes","Fresh fior di latte mozzarella","Fresh basil","Recipe card with QR"],"specs":[{"label":"You add","value":"Warm water and olive oil."},{"label":"Proving time","value":"The dough needs 8 to 24 hours resting in the fridge."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["300 ml warm water","1 tablespoon olive oil"],"steps":[{"title":"The dough (the day before)","text":"Mix the flour, yeast, a teaspoon of salt and the warm water. Knead for 10 minutes until smooth, shape into balls and keep them covered in the fridge for 8 to 24 hours."},{"title":"Bring to room temperature","text":"Take the balls out of the fridge 1 hour before and heat the oven to maximum with the tray inside."},{"title":"Stretch by hand","text":"Press the ball from the centre outwards, leaving a thick edge. No rolling pin: it would squash the air out."},{"title":"Top it","text":"Tomatoes crushed by hand, drained and torn mozzarella, a drizzle of oil."},{"title":"Bake","text":"On the hot tray, 7–9 minutes until the crust is puffed up with charred spots."},{"title":"Basil","text":"Out of the oven, add a few fresh basil leaves. Slice and share (or don’t)."}],"tips":["Use oven gloves to take the tray out: it’s scorching."]},"variants":{"HDM-PIZ-2":"2 pizzas","HDM-PIZ-4":"4 pizzas"},"imageAlts":["Freshly baked margherita pizza","Margherita pizza with fresh mozzarella and basil"]}}'::jsonb, now() - interval '140 days', now() - interval '140 days') on conflict (id) do update set translations = excluded.translations;
