insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('5f0c8f35-90be-4a66-a40b-32ab93b2c7bc', 'kit-poke-salmon', 'Kit Poke de salmón', 'Salmón fresco marinado, arroz de sushi, edamame, mango y aguacate.', 'El bol hawaiano de moda. Llega refrigerado con el salmón fresco apto para comer crudo (previamente congelado), el aguacate, el mango y el pepino; además, arroz para sushi, edamame, salsa poke de soja y sésamo tostado. Tú cueces el arroz y montas el bol.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, 'Nuevo', 20, '{"minutes":35,"difficulty":3,"heat":"cazo","storage":"fresco","nutrition":{"kcal":610,"protein":32,"carbs":72,"fat":20}}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['alto-en-proteina']::text[], array['pescado', 'soja', 'gluten', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["Agua para el arroz y el edamame"],"steps":[{"title":"Lava y cuece el arroz","text":"Lava el arroz hasta que el agua salga clara. Cuécelo tapado con 1,2 veces su volumen de agua 12 minutos a fuego bajo y deja reposar 10."},{"title":"Marina el salmón","text":"Corta el salmón en dados con un cuchillo bien afilado y mézclalo con la mitad de la salsa poke. A la nevera mientras preparas lo demás."},{"title":"Prepara los toppings","text":"Cuece el edamame 3 minutos. Corta en dados el aguacate, el mango y el pepino."},{"title":"Monta el bol","text":"Arroz templado en la base y encima, por grupos, el salmón, el edamame, el aguacate, el mango y el pepino."},{"title":"Termina","text":"Riega con el resto de la salsa y espolvorea el sésamo."}],"tips":["Lávate las manos y usa una tabla limpia para el pescado crudo.","Come el poke el mismo día en que lo montes."]}'::jsonb, array['Lomo de salmón fresco apto para crudo', 'Arroz para sushi', 'Aguacate', 'Mango', 'Pepino', 'Edamame', 'Salsa poke de soja', 'Sésamo tostado', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Salmon poke kit","subtitle":"Marinated fresh salmon, sushi rice, edamame, mango and avocado.","description":"The trendy Hawaiian bowl. It arrives chilled with fresh salmon safe to eat raw (previously frozen), avocado, mango and cucumber, plus sushi rice, edamame, soy poke sauce and toasted sesame. You cook the rice and build the bowl.","badge":"New","includes":["Fresh salmon loin safe to eat raw","Sushi rice","Avocado","Mango","Cucumber","Edamame","Soy poke sauce","Toasted sesame","Recipe card with QR"],"specs":[{"label":"You add","value":"Water."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["Water for the rice and the edamame"],"steps":[{"title":"Rinse and cook the rice","text":"Rinse the rice until the water runs clear. Cook it covered with 1.2 times its volume of water for 12 minutes on low heat and rest for 10."},{"title":"Marinate the salmon","text":"Dice the salmon with a sharp knife and mix it with half the poke sauce. Into the fridge while you prep the rest."},{"title":"Prep the toppings","text":"Boil the edamame for 3 minutes. Dice the avocado, the mango and the cucumber."},{"title":"Build the bowl","text":"Warm rice at the bottom and, in groups on top, the salmon, edamame, avocado, mango and cucumber."},{"title":"Finish","text":"Drizzle with the rest of the sauce and sprinkle with sesame."}],"tips":["Wash your hands and use a clean board for the raw fish.","Eat the poke the same day you make it."]},"variants":{"HDM-POK-2":"Serves 2","HDM-POK-4":"Serves 4"},"imageAlts":["Poke bowl with diced salmon, edamame, mango, cucumber and avocado","Poke bowl with edamame, mango and vegetables"]}}'::jsonb, now() - interval '1 days', now() - interval '1 days') on conflict (id) do update set translations = excluded.translations;
