insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('0a055f1c-838b-4547-b62b-cb7a70b822dd', 'kit-fajitas-pollo', 'Kit Fajitas de pollo', 'Tiras de pollo con pimientos y cebolla a la plancha, tortillas de trigo y salsa.', 'Para cenar con las manos y con la mesa llena. Llega refrigerado con las tiras de pechuga de pollo, pimientos rojo y verde, cebolla y una lima; además, tortillas de trigo, especias para fajitas y salsa de tomate mexicana.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 130, '{"minutes":30,"difficulty":3,"heat":"sarten","storage":"fresco","nutrition":{"kcal":650,"protein":38,"carbs":64,"fat":24}}'::jsonb, '[{"label":"Tú pones","value":"Aceite."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['picante', 'alto-en-proteina']::text[], array['gluten']::text[], array['soja', 'mostaza']::text[], array[]::text[], '{"youAdd":["2 cucharadas de aceite"],"steps":[{"title":"Corta la verdura","text":"Corta los pimientos y la cebolla en tiras finas."},{"title":"Adoba el pollo","text":"Mezcla las tiras de pollo con la mitad de las especias y un chorrito de aceite."},{"title":"Saltea el pollo","text":"Sartén muy caliente: dora el pollo 5-6 minutos hasta que no quede rosa por dentro. Sácalo."},{"title":"Saltea la verdura","text":"En la misma sartén, saltea pimientos y cebolla con el resto de especias 5 minutos. Vuelve a echar el pollo y exprime la lima."},{"title":"Monta","text":"Calienta las tortillas 20 segundos por lado, rellénalas con salsa y el salteado, y enróllalas."}],"tips":["Lávate las manos y la tabla después de cortar el pollo crudo.","No llenes demasiado la tortilla o se romperá al enrollar."]}'::jsonb, array['Tiras de pechuga de pollo fresca', 'Pimiento rojo y verde', 'Cebolla', 'Lima', 'Tortillas de trigo', 'Sobre de especias para fajitas', 'Salsa de tomate mexicana', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Chicken fajitas kit","subtitle":"Seared chicken strips with peppers and onion, flour tortillas and salsa.","description":"For eating with your hands around a full table. It arrives chilled with chicken breast strips, red and green peppers, an onion and a lime, plus flour tortillas, fajita spices and Mexican tomato salsa.","includes":["Fresh chicken breast strips","Red and green pepper","Onion","Lime","Flour tortillas","Fajita spice sachet","Mexican tomato salsa","Recipe card with QR"],"specs":[{"label":"You add","value":"Oil."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["2 tablespoons oil"],"steps":[{"title":"Slice the veg","text":"Cut the peppers and the onion into thin strips."},{"title":"Season the chicken","text":"Mix the chicken strips with half the spices and a splash of oil."},{"title":"Sear the chicken","text":"Very hot pan: brown the chicken for 5–6 minutes until it’s no longer pink inside. Take it out."},{"title":"Stir-fry the veg","text":"In the same pan, stir-fry the peppers and onion with the rest of the spices for 5 minutes. Add the chicken back and squeeze over the lime."},{"title":"Build","text":"Warm the tortillas 20 seconds a side, fill them with salsa and the stir-fry, and roll them up."}],"tips":["Wash your hands and the board after cutting raw chicken.","Don’t overfill the tortilla or it will tear when you roll it."]},"variants":{"HDM-FAJ-2":"Serves 2","HDM-FAJ-4":"Serves 4"},"imageAlts":["Rolled chicken and pepper fajita next to a jar of salsa and half a lime","Grilled chicken strips with peppers and tortillas"]}}'::jsonb, now() - interval '35 days', now() - interval '35 days') on conflict (id) do update set translations = excluded.translations;
