insert into public.product_variants (id, product_id, sku, name, price_cents, compare_at_price_cents, stock, position) values ('b386576a-0aba-4859-bb40-22009aa5d7ef', '0a055f1c-838b-4547-b62b-cb7a70b822dd', 'HDM-FAJ-4', '4 personas', 4190, 4980, 12, 1) on conflict (id) do nothing;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('b6c0fc96-d1e0-4fb9-887f-b898be052633', 'kit-carbonara', 'Kit Espaguetis a la carbonara', 'La de verdad: guanciale, huevo, pecorino y pimienta negra. Sin nata.', 'La receta romana auténtica, con solo cinco ingredientes. Llega refrigerado con el guanciale (papada curada), los huevos frescos y el queso pecorino romano; además, espaguetis de sémola de trigo duro y pimienta negra en grano. El truco está en mezclar fuera del fuego.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 125, '{"minutes":25,"difficulty":3,"heat":"cazo","storage":"fresco","nutrition":{"kcal":720,"protein":30,"carbs":80,"fat":30}}'::jsonb, '[{"label":"Tú pones","value":"Agua y sal."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['alto-en-proteina']::text[], array['gluten', 'huevos', 'leche']::text[], array[]::text[], array[]::text[], '{"youAdd":["2 litros de agua","Sal para el agua de la pasta"],"steps":[{"title":"Pon el agua","text":"Lleva a ebullición el agua con sal y cuece los espaguetis el tiempo del paquete menos 1 minuto."},{"title":"Dora el guanciale","text":"En una sartén sin aceite, a fuego medio, dora el guanciale hasta que suelte la grasa y quede crujiente. Apaga el fuego."},{"title":"Haz la crema","text":"Bate las yemas (y un huevo entero) con casi todo el pecorino y mucha pimienta recién molida."},{"title":"Mezcla fuera del fuego","text":"Pasa la pasta a la sartén del guanciale con un poco de agua de cocción. Ya sin fuego, añade la crema de huevo y remueve rápido hasta que quede sedosa."},{"title":"Sirve","text":"Emplata enseguida con el resto del pecorino y más pimienta."}],"tips":["Si la sartén está muy caliente, el huevo cuaja y se hace tortilla: espera un minuto.","El agua de cocción con almidón es lo que hace la salsa cremosa."]}'::jsonb, array['Espaguetis de trigo duro', 'Guanciale en tiras', 'Huevos frescos', 'Pecorino romano rallado', 'Pimienta negra en grano', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Spaghetti carbonara kit","subtitle":"The real one: guanciale, egg, pecorino and black pepper. No cream.","description":"The authentic Roman recipe, with just five ingredients. It arrives chilled with the guanciale (cured pork cheek), fresh eggs and pecorino romano, plus durum wheat spaghetti and whole black pepper. The trick is mixing it off the heat.","includes":["Durum wheat spaghetti","Guanciale strips","Fresh eggs","Grated pecorino romano","Whole black pepper","Recipe card with QR"],"specs":[{"label":"You add","value":"Water and salt."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["2 litres water","Salt for the pasta water"],"steps":[{"title":"Boil the water","text":"Bring the salted water to the boil and cook the spaghetti for the packet time minus 1 minute."},{"title":"Crisp the guanciale","text":"In a pan with no oil, over medium heat, cook the guanciale until it releases its fat and turns crispy. Turn off the heat."},{"title":"Make the cream","text":"Whisk the yolks (and one whole egg) with most of the pecorino and plenty of freshly ground pepper."},{"title":"Mix off the heat","text":"Move the pasta into the guanciale pan with a little cooking water. With the heat off, add the egg cream and stir fast until silky."},{"title":"Serve","text":"Plate straight away with the rest of the pecorino and more pepper."}],"tips":["If the pan is too hot the egg scrambles: wait a minute.","The starchy cooking water is what makes the sauce creamy."]},"variants":{"HDM-CAR-2":"Serves 2","HDM-CAR-4":"Serves 4"},"imageAlts":["Spaghetti carbonara with guanciale and pecorino in a deep plate","Spaghetti carbonara with grated pecorino"]}}'::jsonb, now() - interval '50 days', now() - interval '50 days') on conflict (id) do update set translations = excluded.translations;
