insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, translations, published_at, created_at) values ('9fbdae99-80e0-4c40-af67-f39fac04e526', 'caja-sobremesa-navidad', 'Caja Sobremesa', 'Edición Navidad. Codillo asado con lombarda, patatas panaderas y turrón para después.', 'En España la Navidad no termina al acabar de comer: empieza la sobremesa, esas horas en las que nadie se levanta de la mesa. Esta caja es para ganártela. El codillo de cerdo llega ya cocinado a baja temperatura durante 12 horas, así que tú solo le das el horno para que la piel quede crujiente, con una salsa de miel y mostaza, patatas panaderas y lombarda con manzana, piñones y pasas, como en casa de los abuelos. Y para la sobremesa, turrón de almendra. Edición limitada: solo se puede encargar, hasta el 10 de diciembre, y sale el 25.', 'f1cef13a-c34d-4a27-bfd1-cb848b558ac9', 1000, 'published', false, true, 'Edición Navidad', 0, '{"minutes":75,"difficulty":3,"heat":"horno","storage":"fresco","nutrition":{"kcal":1050,"protein":62,"carbs":70,"fat":56},"preorder":{"releaseDate":"2026-12-25","closesDate":"2026-12-10"}}'::jsonb, '[{"label":"Tú pones","value":"Aceite y sal."},{"label":"Encargo","value":"Edición limitada. Se puede encargar hasta el 10 de diciembre; después se cierran los encargos."},{"label":"Entrega","value":"Sale el 25 de diciembre. El codillo va ya cocinado: solo necesitas una hora de horno."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['alto-en-proteina']::text[], array['mostaza', 'frutos-de-cascara']::text[], array['huevos', 'leche', 'cacahuetes']::text[], array[]::text[], '{"youAdd":["4 cucharadas de aceite de oliva","Sal"],"steps":[{"title":"Enciende el horno","text":"Precalienta el horno a 200 °C. Saca el codillo de la nevera para que no entre frío."},{"title":"Haz las panaderas","text":"Corta las patatas en rodajas finas y la cebolla en tiras. Ponlas en una bandeja con aceite, sal, el romero y el laurel, y hornéalas 20 minutos."},{"title":"Al horno el codillo","text":"Coloca el codillo encima de las patatas con la piel hacia arriba y píntalo con la mitad de la salsa de miel y mostaza. Hornéalo 40 minutos."},{"title":"Que cruja","text":"Vuelve a pintarlo con el resto de la salsa y sube el horno a 220 °C los últimos 10 minutos, hasta que la piel esté dorada y crujiente."},{"title":"La lombarda","text":"Mientras, calienta la lombarda en una sartén 8 minutos con un chorrito de aceite, los piñones y las pasas."},{"title":"A la mesa","text":"Deja reposar el codillo 5 minutos y sírvelo con las patatas y la lombarda. Usa guantes de horno: la bandeja quema."},{"title":"La sobremesa","text":"Recoge lo justo, saca el turrón y no te levantes. Esa es la receta."}],"tips":["Si la piel no cruje, ponla 3 minutos con el grill del horno, mirando para que no se queme.","El jugo que queda en la bandeja está buenísimo: échalo por encima al servir."]}'::jsonb, array['Codillo de cerdo cocinado 12 h (uno por persona)', 'Patatas para hacer panaderas', 'Cebolla', 'Lombarda cocida con manzana', 'Piñones y pasas', 'Salsa de miel y mostaza antigua', 'Romero y laurel', 'Turrón de almendra para la sobremesa', 'Tarjeta de receta con QR']::text[], '{"en":{"name":"Sobremesa box","badge":"Christmas edition","subtitle":"Christmas edition. Roast pork knuckle with red cabbage, sliced roast potatoes and turrón for afterwards.","description":"In Spain, Christmas doesn''t end when the meal does: that''s when the sobremesa starts, the hours when nobody gets up from the table. This box is how you earn it. The pork knuckle (codillo) arrives already slow-cooked for 12 hours, so you just give it time in the oven for crackling skin, with a honey and mustard glaze, sliced roast potatoes and red cabbage with apple, pine nuts and raisins, like at your grandparents''. And for the sobremesa, almond turrón. Limited edition: pre-order only, until 10 December, and it comes out on the 25th.","includes":["Pork knuckle cooked for 12 h (one per person)","Potatoes for slicing and roasting","Onion","Red cabbage cooked with apple","Pine nuts and raisins","Honey and wholegrain mustard glaze","Rosemary and bay leaves","Almond turrón for the sobremesa","Recipe card with QR"],"specs":[{"label":"You add","value":"Oil and salt."},{"label":"Pre-order","value":"Limited edition. Pre-orders are open until 10 December; after that they close."},{"label":"Delivery","value":"Out on 25 December. The knuckle is already cooked: you only need an hour of oven time."},{"label":"Storage","value":"Arrives chilled. Put the fresh items in the fridge as soon as it arrives and cook within 3 days."},{"label":"Recipe","value":"Card with a QR code: scan it to see the step-by-step recipe on your phone."}],"recipe":{"youAdd":["4 tablespoons of olive oil","Salt"],"steps":[{"title":"Turn on the oven","text":"Preheat the oven to 200 °C. Take the knuckle out of the fridge so it doesn’t go in cold."},{"title":"Make the potatoes","text":"Slice the potatoes thinly and the onion into strips. Put them on a tray with oil, salt, the rosemary and bay leaves, and roast for 20 minutes."},{"title":"Knuckle in the oven","text":"Put the knuckle on top of the potatoes, skin side up, and brush it with half the honey and mustard glaze. Roast for 40 minutes."},{"title":"Make it crackle","text":"Brush it with the rest of the glaze and turn the oven up to 220 °C for the last 10 minutes, until the skin is golden and crisp."},{"title":"The red cabbage","text":"Meanwhile, warm the red cabbage in a pan for 8 minutes with a splash of oil, the pine nuts and the raisins."},{"title":"To the table","text":"Let the knuckle rest for 5 minutes and serve it with the potatoes and cabbage. Use oven gloves: the tray is very hot."},{"title":"The sobremesa","text":"Clear just enough, bring out the turrón and stay seated. That’s the recipe."}],"tips":["If the skin doesn’t crackle, give it 3 minutes under the oven grill, watching so it doesn’t burn.","The juices left in the tray are delicious: pour them over when you serve."]},"variants":{"HDM-NAV-2":"Serves 2","HDM-NAV-4":"Serves 4"},"imageAlts":["Roast pork knuckle with golden, crackling skin","Roast pork knuckle with the bone showing"]}}'::jsonb, now() - interval '0 days', now() - interval '0 days') on conflict (id) do update set translations = excluded.translations;
